import VOTCoreClient from "@vot.js/core/client";
import { VOTAgent } from "./utils/fetchAgent.js";
export default class VOTClient extends VOTCoreClient {
    constructor(opts) {
        super(opts);
        this.setFetchOpts();
    }
    setFetchOpts() {
        this.provider.fetchOpts = {
            dispatcher: new VOTAgent(),
            ...this.provider.fetchOpts,
        };
        return this;
    }
}
