import { BaseHelper } from "./base.js";
export default class SpankBangHelper extends BaseHelper {
    async getVideoId(url) {
        return (/\/([\da-z]+\/(?:video|play|embed)(?:\/[^/]+)?)\/?$/i.exec(url.pathname)?.[1] ??
            /\/([\da-z]+-[\da-z]+\/playlist\/[^/]+)\/?$/i.exec(url.pathname)?.[1]);
    }
}
