import { config } from "@vot.js/shared";
import { fetchWithTimeout } from "@vot.js/shared/utils/utils";
export class BaseProvider {
    host;
    schema;
    fetch;
    fetchOpts;
    userAgent = config.userAgent;
    requestLang;
    responseLang;
    headers = {
        "User-Agent": this.userAgent,
        "Accept-Language": "en",
        Pragma: "no-cache",
        "Cache-Control": "no-cache",
    };
    hostSchemaRe = /(http(s)?):\/\//;
    constructor({ host = config.host, fetchFn = fetchWithTimeout, fetchOpts = {}, headers = {}, requestLang = "en", responseLang = "ru", } = {}) {
        const schema = this.hostSchemaRe.exec(host)?.[1];
        this.host = schema ? host.replace(`${schema}://`, "") : host;
        this.schema = schema ?? "https";
        this.fetch = fetchFn;
        this.fetchOpts = fetchOpts;
        this.headers = { ...this.headers, ...headers };
        this.requestLang = requestLang;
        this.responseLang = responseLang;
    }
    async request(path, body, headers = {}, method = "POST") {
        const options = this.getOpts(new Blob([body]), headers, method);
        try {
            const res = await this.fetch(`${this.schema}://${this.host}${path}`, options);
            const data = (await res.arrayBuffer());
            return {
                success: res.status === 200,
                data,
            };
        }
        catch (err) {
            return {
                success: false,
                data: err?.message,
            };
        }
    }
    async requestJSON(path, body = null, headers = {}, method = "POST") {
        const options = this.getOpts(body, {
            "Content-Type": "application/json",
            ...headers,
        }, method);
        try {
            const res = await this.fetch(`${this.schema}://${this.host}${path}`, options);
            const data = (await res.json());
            return {
                success: res.status === 200,
                data,
            };
        }
        catch (err) {
            return {
                success: false,
                data: err?.message,
            };
        }
    }
    getOpts(body, headers = {}, method = "POST") {
        return {
            method,
            headers: {
                ...this.headers,
                ...headers,
            },
            body,
            ...this.fetchOpts,
        };
    }
}
